    pricing: { label: 'RegisterBox MSME/Udyam assistance', value: '₹499', price: 499, currency: 'INR', note: 'For optional MSME/Udyam preparation assistance. No GST is added. Other work is quoted separately; the official Udyam portal registration is free.' },
    eligibility: ['Choose a lawful activity and structure suited to ownership, liability, tax, funding and exit.', 'Identify sector and location approvals before committing to premises or operations.', 'DPIIT recognition, Udyam and tax incentives have separate tests and are not automatic.', 'Foreign ownership, regulated activities and professional services require added review.'],
    documents: ['Founder identity, address, ownership and contact information.', 'Activity, products/services, customers, locations and expected-turnover summary.', 'Ownership, investment, profit-share or capital decisions.', 'Premises/workforce plan and sector-specific qualifications or NOCs.', 'Existing PAN, registrations, agreements or brand material.'],
    governmentFees: ['There is no single government fee; incorporation, stamp duty and licences are separate.', 'Official Udyam registration is free and paperless. Optional RegisterBox preparation assistance is ₹499, with no GST added.', 'NSWS registration is free; responsible authorities may charge for approvals.', 'Other RegisterBox business-registration or approval work is scoped and quoted separately.'],
    timeline: ['Structure and approval mapping: commonly 1–3 business days after a complete questionnaire.', 'Entity/tax registrations often take days to weeks; premises or sector approvals can take longer.', 'Plan around the slowest mandatory pre-operation approval, not only incorporation.'],
    process: ['Describe activity, owners, customers, channels, locations, workforce and funding.', 'Compare structures and record the reason for the choice.', 'Use official tools to map Central, State and local approvals.', 'Sequence entity, tax, labour, sector, premises and banking work.', 'Submit each approved application and verify issued results.', 'Create a recurring compliance calendar.'],
    rejectionReasons: ['Choosing an entity before resolving ownership/funding restrictions.', 'Conflicting name, unclear activity or incomplete founder KYC.', 'Premises unsuitable for the intended approval.', 'Assuming incorporation, Udyam or DPIIT replaces sector licences.', 'Inconsistent names, addresses or activities across portals.'],
    stateNotes: ['Shops, professional tax, trade, fire, pollution and land use vary by State/local body.', 'Stamp duty and linked registrations change with registered-office State.', 'Use NSWS and State portals, then verify the responsible authority.'],
    registerBoxHelp: ['Turn the idea into a structure comparison and approval map.', 'Create one verified profile for consistent facts.', 'Sequence registrations and assign document owners/deadlines.', 'Separate government payments from assisted-work estimates.'],
    question: 'Should every founder register a private limited company first?',
